37	
38	public class DepositSnapshotFileLoader {
39	
40	  public static final Map<Eth2Network, String> DEFAULT_SNAPSHOT_RESOURCE_PATHS =
41	      Map.of(
42	          Eth2Network.GNOSIS, "gnosis.ssz",
43	          Eth2Network.PRATER, "goerli.ssz",
44	          Eth2Network.MAINNET, "mainnet.ssz",
45	          Eth2Network.SEPOLIA, "sepolia.ssz",
46	          Eth2Network.LUKSO, "lukso.ssz",
47	          Eth2Network.HOLESKY, "holesky.ssz");
48	
49	  private static final Logger LOG = LogManager.getLogger();
50	
51	  private final Optional<String> depositSnapshotResource;
52	
53	  public DepositSnapshotFileLoader(final Optional<String> depositSnapshotResource) {
54	    this.depositSnapshotResource = depositSnapshotResource;
55	  }
56	
57	  public LoadDepositSnapshotResult loadDepositSnapshot() {
58	    final Optional<DepositTreeSnapshot> depositTreeSnapshot =
59	        loadDepositSnapshot(depositSnapshotResource);
60	    return LoadDepositSnapshotResult.create(depositTreeSnapshot);
61	  }
62	
63	  private Optional<DepositTreeSnapshot> loadDepositSnapshot(
64	      final Optional<String> depositSnapshotResource) {
65	    return depositSnapshotResource.map(
66	        snapshotPath -> {
67	          final String sanitizedResource = UrlSanitizer.sanitizePotentialUrl(snapshotPath);
68	          try {
69	            STATUS_LOG.loadingDepositSnapshotResource(sanitizedResource);
70	            final DepositTreeSnapshot depositSnapshot = loadFromUrl(snapshotPath);
71	            STATUS_LOG.onDepositSnapshot(
72	                depositSnapshot.getDepositCount(), depositSnapshot.getExecutionBlockHash());
73	            return depositSnapshot;
74	          } catch (IOException e) {
75	            LOG.error("Failed to load deposit tree snapshot", e);
76	            throw new InvalidConfigurationException(
77	                "Failed to load deposit tree snapshot from "
78	                    + sanitizedResource
79	                    + ": "
80	                    + e.getMessage());
81	          }
82	        });
83	  }
84	
85	  private DepositTreeSnapshot loadFromUrl(final String path) throws IOException {
86	    final Bytes snapshotData =
87	        ResourceLoader.urlOrFile("application/octet-stream, application/json")
88	            .loadBytes(path)
89	            .orElseThrow(
90	                () -> new FileNotFoundException(String.format("File '%s' not found", path)));
91	
92	    try {
93	      return parseSszDepositSnapshotTreeData(snapshotData);
94	    } catch (final SszDeserializeException e) {
95	      return parseJsonDepositSnapshotTreeData(snapshotData);
96	    }
97	  }
98	
99	  private static DepositTreeSnapshot parseSszDepositSnapshotTreeData(final Bytes snapshotData) {
100	    return DepositTreeSnapshot.fromBytes(snapshotData);
101	  }
102	
103	  private static DepositTreeSnapshot parseJsonDepositSnapshotTreeData(final Bytes snapshotData)
104	      throws JsonProcessingException {
105	    final String json = new String(snapshotData.toArray(), StandardCharsets.UTF_8);
106	    final JsonNode jsonNode = new ObjectMapper().readTree(json);
107	    return JsonUtil.parse(
108	        jsonNode.get("data").toString(), DepositTreeSnapshot.getJsonTypeDefinition());
109	  }
110	}
