62	  @Test
63	  public void shouldHaveCorrectDepositsData_whenSnapshotLoaded() {
64	    final int deposits = 16646;
65	    final int blockNumber = 1033803;
66	    final LoadDepositSnapshotResult result = depositSnapshotLoader.loadDepositSnapshot();
67	    assertWith(
68	        result,
69	        snapshotResult -> {
70	          assertThat(snapshotResult.getDepositTreeSnapshot().isPresent()).isTrue();
71	          assertThat(snapshotResult.getDepositTreeSnapshot().get().getDepositCount())
72	              .isEqualTo(deposits);
73	          assertThat(snapshotResult.getReplayDepositsResult().getLastProcessedDepositIndex())
74	              .contains(BigInteger.valueOf(deposits - 1));
75	          assertThat(snapshotResult.getReplayDepositsResult().getLastProcessedBlockNumber())
76	              .isEqualTo(blockNumber);
77	        });
78	  }
