82	    // From deposit_tree_snapshot_beaconAPI.json file
83	    final int deposits = 1106572;
84	    final int blockNumber = 18754822;
85	
86	    depositSnapshotLoader =
87	        new DepositSnapshotFileLoader(
88	            Optional.of(getResourceFilePath(SNAPSHOT_BEACON_API_RESOURCE)));
89	    final LoadDepositSnapshotResult result = depositSnapshotLoader.loadDepositSnapshot();
90	
91	    assertWith(
92	        result,
93	        snapshotResult -> {
94	          assertThat(snapshotResult.getDepositTreeSnapshot().isPresent()).isTrue();
95	          assertThat(snapshotResult.getDepositTreeSnapshot().get().getDepositCount())
96	              .isEqualTo(deposits);
97	          assertThat(snapshotResult.getReplayDepositsResult().getLastProcessedDepositIndex())
98	              .contains(BigInteger.valueOf(deposits - 1));
99	          assertThat(snapshotResult.getReplayDepositsResult().getLastProcessedBlockNumber())
100	              .isEqualTo(blockNumber);
101	        });
102	  }
